package Day3;
import java.util.*;
public class Assignment_Operator {

	public static void main(String[] args) {
		
		// TODO Auto-generated method stub
		int bank_balance=5000;
		System.out.println("initial Balance "+bank_balance);
		bank_balance+=1000;
		System.out.println("after deposit "+bank_balance);
		bank_balance-=1000;
		System.out.println("after withdrawal  "+bank_balance);
		bank_balance*=2;
		System.out.println("Bank balance multiply with 2   "+bank_balance);
		bank_balance/=2;
		System.out.println("Bank balance div by  2   "+bank_balance);
		bank_balance%=2;
		System.out.println("Bank balance mod by  with 2   "+bank_balance);
		
		
		
		

	}

}
